import { useMemo, useState } from 'react'
import { QRCodeSVG } from 'qrcode.react'
import {
  CalendarDays,
  MapPin,
  Search,
  ShieldCheck,
  Download,
  RefreshCw,
  Ticket,
  Building2,
  AlertCircle,
} from 'lucide-react'
import { supabase } from '../lib/supabase'

const OFFICIAL_LOGO_DATA_URL = 'data:image/png;base64,'

type PortalBranding = {
  organization_name: string
  official_logo_url: string | null
  color_primary: string
  color_secondary: string
  color_accent: string
  color_background: string
  color_surface: string
  color_text: string
  event_logos: Array<{ display_name: string; logo_url: string }>
}

type LookupResponse = {
  success: true
  event: {
    name: string
    description: string | null
    event_date: string | null
    location: string | null
    branding: PortalBranding
  }
  guest: {
    name: string
    institution: string | null
    category: string
    guest_group: string | null
    invitation_code: string
    invite_token: string
    status: string
  }
}

function getPortalSlug(): string {
  const segment = window.location.pathname.split('/')[2] || ''
  try {
    return decodeURIComponent(segment)
  } catch {
    return ''
  }
}

function formatEventDate(value: string | null): string | null {
  if (!value) return null
  const date = new Date(`${value.slice(0, 10)}T00:00:00`)
  if (Number.isNaN(date.getTime())) return value
  return new Intl.DateTimeFormat('id-ID', {
    day: 'numeric',
    month: 'long',
    year: 'numeric',
  }).format(date)
}

function loadImage(src: string): Promise<HTMLImageElement> {
  return new Promise((resolve, reject) => {
    const image = new Image()
    image.crossOrigin = 'anonymous'
    image.onload = () => resolve(image)
    image.onerror = () => reject(new Error('Gambar logo tidak dapat dimuat.'))
    image.src = src
  })
}

function drawContainedImage(
  ctx: CanvasRenderingContext2D,
  image: HTMLImageElement,
  x: number,
  y: number,
  width: number,
  height: number,
) {
  const scale = Math.min(width / image.naturalWidth, height / image.naturalHeight)
  const drawWidth = image.naturalWidth * scale
  const drawHeight = image.naturalHeight * scale
  ctx.drawImage(image, x + (width - drawWidth) / 2, y + (height - drawHeight) / 2, drawWidth, drawHeight)
}

function drawWrappedText(
  ctx: CanvasRenderingContext2D,
  value: string,
  x: number,
  y: number,
  maxWidth: number,
  lineHeight: number,
  maxLines: number,
) {
  const words = value.trim().split(/\s+/)
  const lines: string[] = []
  let line = ''
  for (const word of words) {
    const candidate = line ? `${line} ${word}` : word
    if (ctx.measureText(candidate).width > maxWidth && line) {
      lines.push(line)
      line = word
    } else {
      line = candidate
    }
  }
  if (line) lines.push(line)
  const visibleLines = lines.slice(0, maxLines)
  if (lines.length > maxLines) {
    let last = visibleLines[maxLines - 1]
    while (last.length && ctx.measureText(`${last}…`).width > maxWidth) last = last.slice(0, -1)
    visibleLines[maxLines - 1] = `${last}…`
  }
  visibleLines.forEach((item, index) => ctx.fillText(item, x, y + index * lineHeight))
  return visibleLines.length
}

export default function PortalPage() {
  const slug = useMemo(getPortalSlug, [])
  const [code, setCode] = useState('')
  const [result, setResult] = useState<LookupResponse | null>(null)
  const [error, setError] = useState('')
  const [loading, setLoading] = useState(false)
  const [downloading, setDownloading] = useState(false)

  async function lookupInvitation(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault()
    setError('')
    setResult(null)

    const normalizedCode = code.trim().toUpperCase()
    if (!slug || !normalizedCode) {
      setError('Masukkan kode undangan Anda terlebih dahulu.')
      return
    }

    setLoading(true)
    try {
      const { data, error: invokeError } = await supabase.functions.invoke(
        'lookup-invitation',
        { body: { slug, code: normalizedCode } },
      )

      if (invokeError) {
        let message = 'Pencarian undangan belum berhasil. Silakan coba kembali.'
        const context = (invokeError as { context?: unknown }).context
        if (context instanceof Response) {
          try {
            const payload = await context.clone().json()
            if (typeof payload?.message === 'string') message = payload.message
          } catch {
            // Gunakan pesan umum jika respons tidak berupa JSON.
          }
        }
        throw new Error(message)
      }

      if (!data?.success || !data?.guest || !data?.event) {
        throw new Error(data?.message || 'Kode undangan tidak ditemukan.')
      }

      setResult(data as LookupResponse)
    } catch (lookupError) {
      setError(
        lookupError instanceof Error
          ? lookupError.message
          : 'Terjadi kendala saat mencari undangan.',
      )
    } finally {
      setLoading(false)
    }
  }

  async function downloadGuestCard() {
    if (!result) return
    const qrSvg = document.getElementById('portal-invite-qr')
    if (!(qrSvg instanceof SVGSVGElement)) {
      setError('QR belum siap. Silakan coba kembali.')
      return
    }

    setDownloading(true)
    setError('')
    let qrObjectUrl = ''
    try {
      const canvas = document.createElement('canvas')
      canvas.width = 1600
      canvas.height = 900
      const ctx = canvas.getContext('2d')
      if (!ctx) throw new Error('Tidak dapat menyiapkan kartu PNG.')

      // Identitas kartu selalu hijau Riyadlul Jannah, tidak mengikuti warna biru lama.
      const primary = '#008b5a'
      const darkGreen = '#075b3d'
      const accent = '#18a66a'

      // Latar dan bingkai kartu.
      ctx.fillStyle = '#f2f6f3'
      ctx.fillRect(0, 0, 1600, 900)
      ctx.fillStyle = '#ffffff'
      ctx.beginPath()
      ctx.roundRect(28, 28, 1544, 844, 48)
      ctx.fill()

      // Gelombang footer hijau yang menjadi identitas kartu.
      ctx.fillStyle = '#e5ece8'
      ctx.beginPath()
      ctx.moveTo(28, 620)
      ctx.bezierCurveTo(390, 790, 720, 790, 1110, 620)
      ctx.bezierCurveTo(1300, 535, 1450, 530, 1572, 555)
      ctx.lineTo(1572, 872)
      ctx.lineTo(28, 872)
      ctx.closePath()
      ctx.fill()
      ctx.fillStyle = primary
      ctx.beginPath()
      ctx.moveTo(28, 665)
      ctx.bezierCurveTo(390, 835, 740, 835, 1115, 665)
      ctx.bezierCurveTo(1320, 570, 1450, 575, 1572, 600)
      ctx.lineTo(1572, 872)
      ctx.lineTo(28, 872)
      ctx.closePath()
      ctx.fill()

      // Logo resmi lembaga di bagian kepala kartu.
      let officialLogo: HTMLImageElement | null = null
      try {
        officialLogo = await loadImage(
          result.event.branding?.official_logo_url || OFFICIAL_LOGO_DATA_URL,
        )
      } catch {
        // Jika URL logo dari pengaturan event gagal dimuat, gunakan logo lembaga bawaan.
        try { officialLogo = await loadImage(OFFICIAL_LOGO_DATA_URL) } catch { officialLogo = null }
      }
      if (officialLogo) {
        drawContainedImage(ctx, officialLogo, 92, 62, 150, 132)
      }

      ctx.fillStyle = '#173c2d'
      ctx.font = 'bold 38px Arial'
      ctx.fillText(result.event.branding?.organization_name || 'Riyadlul Jannah', 270, 112)
      ctx.fillStyle = '#60766b'
      ctx.font = 'bold 20px Arial'
      ctx.fillText('IDENTITAS TAMU UNDANGAN', 272, 150)

      // Logo-logo tambahan event (tidak menggantikan logo lembaga).
      const eventLogos = result.event.branding?.event_logos || []
      const logoSlots = eventLogos.slice(0, 4)
      const logoImages = await Promise.all(logoSlots.map(async item => {
        try { return await loadImage(item.logo_url) } catch { return null }
      }))
      logoImages.forEach((image, index) => {
        if (!image) return
        const slotX = 1050 + index * 120
        ctx.fillStyle = '#ffffff'
        ctx.beginPath()
        ctx.roundRect(slotX, 72, 100, 92, 14)
        ctx.fill()
        drawContainedImage(ctx, image, slotX + 9, 80, 82, 76)
      })

      // Informasi undangan dan identitas tamu.
      ctx.fillStyle = accent
      ctx.font = 'bold 23px Arial'
      ctx.fillText('UNDANGAN RESMI', 100, 285)
      ctx.fillStyle = '#173c2d'
      ctx.font = 'bold 58px Arial'
      const eventLines = drawWrappedText(ctx, result.event.name, 100, 365, 930, 66, 2)

      // Nama tamu adalah identitas utama; institusi ditampilkan sebagai informasi pendukung.
      const guestNameY = 365 + Math.max(1, eventLines) * 54 + 34
      ctx.fillStyle = '#173c2d'
      ctx.font = 'bold 43px Arial'
      const guestNameLines = drawWrappedText(ctx, result.guest.name || 'Tamu Undangan', 102, guestNameY, 930, 50, 2)

      let guestMetaY = guestNameY + Math.max(1, guestNameLines) * 50 + 10
      if (result.guest.institution) {
        ctx.fillStyle = '#587064'
        ctx.font = '28px Arial'
        drawWrappedText(ctx, result.guest.institution, 102, guestMetaY, 930, 34, 1)
        guestMetaY += 48
      }
      ctx.fillStyle = '#087f50'
      ctx.font = 'bold 25px Arial'
      ctx.fillText(`Kategori: ${result.guest.category || '-'}`, 102, guestMetaY)
      ctx.fillStyle = '#587064'
      ctx.font = '25px Arial'
      ctx.fillText(`Kelompok: ${result.guest.guest_group || '-'}`, 102, guestMetaY + 45)

      // Panel QR di sisi kanan.
      const qrClone = qrSvg.cloneNode(true) as SVGSVGElement
      qrClone.setAttribute('xmlns', 'http://www.w3.org/2000/svg')
      qrClone.setAttribute('width', '560')
      qrClone.setAttribute('height', '560')
      const qrBlob = new Blob([new XMLSerializer().serializeToString(qrClone)], { type: 'image/svg+xml;charset=utf-8' })
      qrObjectUrl = URL.createObjectURL(qrBlob)
      const qrImage = await loadImage(qrObjectUrl)

      ctx.fillStyle = '#ffffff'
      ctx.beginPath()
      ctx.roundRect(1110, 245, 390, 390, 30)
      ctx.fill()
      ctx.imageSmoothingEnabled = false
      ctx.drawImage(qrImage, 1140, 275, 330, 330)
      ctx.imageSmoothingEnabled = true
      ctx.fillStyle = darkGreen
      ctx.textAlign = 'center'
      ctx.font = 'bold 24px Arial'
      ctx.fillText('SCAN UNTUK CHECK-IN', 1305, 682)
      ctx.textAlign = 'left'

      // Kode undangan dan informasi acara di footer.
      ctx.fillStyle = '#ffffff'
      ctx.font = 'bold 22px Arial'
      ctx.fillText('KODE UNDANGAN', 102, 785)
      ctx.font = 'bold 42px Arial'
      ctx.fillText(result.guest.invitation_code, 102, 835)
      ctx.textAlign = 'right'
      ctx.font = 'bold 24px Arial'
      ctx.fillText(result.event.name, 1500, 785, 700)
      ctx.font = '20px Arial'
      const dateText = formatEventDate(result.event.event_date) || ''
      const locationText = result.event.location || ''
      ctx.fillText([dateText, locationText].filter(Boolean).join('  •  '), 1500, 825, 700)
      ctx.textAlign = 'left'

      const pngBlob = await new Promise<Blob>((resolve, reject) => {
        canvas.toBlob(blob => blob ? resolve(blob) : reject(new Error('Gagal membuat file PNG.')), 'image/png')
      })
      const downloadUrl = URL.createObjectURL(pngBlob)
      const link = document.createElement('a')
      link.href = downloadUrl
      link.download = `Kartu-Tamu-${result.guest.invitation_code}.png`
      document.body.appendChild(link)
      link.click()
      link.remove()
      URL.revokeObjectURL(downloadUrl)
    } catch (downloadError) {
      console.error('Gagal membuat kartu identitas:', downloadError)
      setError(downloadError instanceof Error ? downloadError.message : 'Gagal membuat kartu identitas PNG.')
    } finally {
      if (qrObjectUrl) URL.revokeObjectURL(qrObjectUrl)
      setDownloading(false)
    }
  }

  const branding = result?.event.branding
  const qrUrl = result
    ? `${window.location.origin}/undangan/${result.guest.invite_token}`
    : ''

  return (
    <main
      className="portal-page"
      style={{
        '--portal-primary': branding?.color_primary || '#087f50',
        '--portal-secondary': branding?.color_secondary || '#159866',
        '--portal-accent': branding?.color_accent || '#20a36f',
        '--portal-background': branding?.color_background || '#f2f7f3',
        '--portal-surface': branding?.color_surface || '#ffffff',
        '--portal-text': branding?.color_text || '#173c2d',
      } as React.CSSProperties}
    >
      <div className="portal-wrap">
        <header className="portal-header">
          <div className="portal-official-brand">
            <img
              src={branding?.official_logo_url || OFFICIAL_LOGO_DATA_URL}
              alt={branding?.organization_name || 'Logo resmi lembaga'}
              onError={event => { event.currentTarget.src = OFFICIAL_LOGO_DATA_URL }}
            />
            <span>
              <strong>{branding?.organization_name || 'Riyadlul Jannah'}</strong>
              <small>PORTAL UNDANGAN DIGITAL</small>
            </span>
          </div>
          {branding?.event_logos?.length ? (
            <div className="portal-event-logos" aria-label="Logo pendukung acara">
              {branding.event_logos.map((logo, index) => (
                <img key={`${logo.logo_url}-${index}`} src={logo.logo_url} alt={logo.display_name} />
              ))}
            </div>
          ) : null}
        </header>

        <section className="portal-main-card">
          <div className="portal-heading">
            <span className="portal-kicker">UNDANGAN RESMI</span>
            <h1>Temukan Undangan Anda</h1>
            <p>Masukkan kode undangan yang tercantum pada undangan yang Anda terima.</p>
          </div>

          <form className="portal-search-form" onSubmit={lookupInvitation}>
            <label htmlFor="portal-invitation-code">Kode Undangan</label>
            <div className="portal-input-wrap">
              <Ticket size={19} />
              <input
                id="portal-invitation-code"
                type="text"
                value={code}
                onChange={event => setCode(event.target.value.toUpperCase())}
                placeholder="Contoh: ER-XXXXXXXX"
                autoComplete="off"
                autoCapitalize="characters"
                spellCheck={false}
                maxLength={40}
                required
              />
            </div>
            <button className="portal-submit" type="submit" disabled={loading}>
              {loading ? <RefreshCw size={18} className="portal-spin" /> : <Search size={18} />}
              {loading ? 'Mencari undangan...' : 'Cari Undangan'}
            </button>
          </form>

          {error ? (
            <div className="portal-error" role="alert">
              <AlertCircle size={18} />
              <span>{error}</span>
            </div>
          ) : null}

          {result ? (
            <section className="portal-result" aria-live="polite">
              <div className="portal-result-heading">
                <span className="portal-result-check"><ShieldCheck size={19} /></span>
                <div>
                  <span>UNDANGAN DITEMUKAN</span>
                  <h2>{result.event.name}</h2>
                </div>
              </div>

              {result.event.description ? (
                <p className="portal-event-description">{result.event.description}</p>
              ) : null}

              <div className="portal-event-meta">
                {formatEventDate(result.event.event_date) ? (
                  <span><CalendarDays size={16} />{formatEventDate(result.event.event_date)}</span>
                ) : null}
                {result.event.location ? (
                  <span><MapPin size={16} />{result.event.location}</span>
                ) : null}
              </div>

              <div className="portal-guest-card">
                <span className="portal-guest-label">UNDANGAN DITUJUKAN KEPADA</span>
                <h3>{result.guest.name}</h3>
                {result.guest.institution ? (
                  <p><Building2 size={15} />{result.guest.institution}</p>
                ) : null}
                <div className="portal-guest-tags">
                  <span>{result.guest.category}</span>
                  {result.guest.guest_group ? <span>{result.guest.guest_group}</span> : null}
                </div>
                <div className="portal-code-display">
                  <small>KODE UNDANGAN</small>
                  <strong>{result.guest.invitation_code}</strong>
                </div>
              </div>

              <div className="portal-qr-section">
                <h3>QR Code Undangan</h3>
                <p>Tunjukkan QR ini kepada petugas saat registrasi.</p>
                <div className="portal-qr-frame">
                  <QRCodeSVG id="portal-invite-qr" value={qrUrl} size={220} level="H" includeMargin />
                </div>
                <button type="button" className="portal-download" onClick={downloadGuestCard} disabled={downloading}>
                  <Download size={17} /> {downloading ? 'Menyiapkan kartu PNG...' : 'Unduh Kartu Identitas PNG'}
                </button>
                <p className="portal-private-note">
                  QR ini bersifat pribadi. Jangan membagikan QR atau tautan undangan kepada orang lain.
                </p>
              </div>
            </section>
          ) : null}
        </section>

        <footer className="portal-footer">
          <span>© {new Date().getFullYear()} EventCheckRijan</span>
          <span>Portal Undangan Digital</span>
        </footer>
      </div>
    </main>
  )
}
